import {createWarehouseMap,hasCoordinates} from './warehouse-map.js';
import {warehouseRepository} from './auth-client.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let rows=[],editing=null,sharing=null,callbacks={},warehouseMap=null;
export async function refreshWarehouses(){try{rows=await warehouseRepository.list();$('#warehouseListError').textContent='';render()}catch(e){$('#warehouseListError').textContent=e.message;throw e}}
function render(){const current=window.wsmsSession?.warehouse?.id||'';$('#projectName').innerHTML='<option value="">Choose a warehouse</option>'+rows.map(w=>`<option value="${esc(w.id)}">${esc(w.name)}</option>`).join('');$('#projectName').value=current;const missing=rows.filter(w=>!hasCoordinates(w));if(!warehouseMap){$('#warehouseList').innerHTML=`<div class="warehouseMapShell"><div class="warehouseMapToolbar"><span id="mappedWarehouseCount"></span><button id="worldMapReset" type="button">⛶ World view</button></div><div id="warehouseMap" role="region" aria-label="Warehouse locations map"></div><p class="mapTileStatus" hidden>Map tiles could not load. Pins remain available; check your connection or try again later.</p><div class="warehouseMapHint">Select a numbered cluster to explore an area. Select a pin for warehouse details.</div></div><div id="unmappedWarehouses"></div><div id="emptyMapNotice" hidden><p>Your warehouse map starts here. Add a warehouse to place its first pin.</p><button data-new-warehouse>＋ Create warehouse</button></div>`;warehouseMap=createWarehouseMap($('#warehouseMap'),rows);$('#worldMapReset').onclick=()=>warehouseMap.reset();}else warehouseMap.update(rows);$('#mappedWarehouseCount').textContent=`${rows.length-missing.length} warehouse${rows.length-missing.length===1?'':'s'} mapped · ${rows.length} accessible`;
$('#unmappedWarehouses').innerHTML=missing.length?`<div class="unmappedHeader"><h2>Locations needed</h2><p>Add coordinates to place these warehouses on the map.</p></div>${missing.map(w=>`<div class="unmappedWarehouse"><div><strong>${esc(w.name)}</strong><small>${esc(w.location)||'Location not set'}</small></div><span class="roleBadge">${esc(w.role)}</span>${w.role!=='viewer'?`<button data-edit-warehouse="${esc(w.id)}">Add coordinates</button>`:'<span>Ask the owner to add coordinates</span>'}<button data-overview-launch="${esc(w.id)}">Overview ↗</button></div>`).join('')}`:'';$('#emptyMapNotice').hidden=!!rows.length;}

function edit(w=null){editing=w?.id||null;$('#warehouseDialogTitle').textContent=w?'Warehouse details':'New warehouse';const form=$('#warehouseForm');for(const key of ['name','country','location','latitude','longitude'])form.elements[key].value=w?.[key]??'';$('#warehouseFormError').textContent='';$('#warehouseDialog').showModal();form.elements.name.focus();}
async function open(id,destination){const selector=$('#projectName'),previous=window.wsmsSession?.warehouse?.id||'';selector.disabled=true;$('#warehouseSwitchError').textContent='';try{await callbacks.beforeOpen?.();const data=await warehouseRepository.load(id);if(destination==='editor'&&(data.warehouse.latitude==null||data.warehouse.longitude==null)){edit(data.warehouse);$('#warehouseFormError').textContent='Add latitude and longitude before opening the editor.';selector.value=previous;return false}await callbacks.onOpen?.(data,destination);$('#warehouseListError').textContent='';return true}catch(e){$('#warehouseListError').textContent=e.message;$('#warehouseSwitchError').textContent=e.message;selector.value=previous;return false}finally{selector.disabled=false}}
async function renderSharing(){try{const members=await warehouseRepository.members(sharing);$('#memberList').innerHTML=members.map(m=>`<div class="memberRow"><div><b>${esc(m.email)}</b><small>${esc(m.role)}</small></div>${m.role==='owner'?'<span class="roleBadge">Owner</span>':`<select aria-label="Role for ${esc(m.email)}" data-member-role="${esc(m.email)}"><option value="viewer" ${m.role==='viewer'?'selected':''}>Viewer</option><option value="editor" ${m.role==='editor'?'selected':''}>Editor</option></select><button data-remove-member="${esc(m.email)}">Remove</button>`}</div>`).join('')}catch(e){$('#sharingError').textContent=e.message}}
export async function initWarehouses(handlers){callbacks=handlers;$('#projectName').onchange=async e=>{if(!e.target.value){e.target.value=window.wsmsSession?.warehouse?.id||'';return}if(e.target.value&&e.target.value!==window.wsmsSession?.warehouse?.id)await open(e.target.value,'overview')};$('#newWarehouse').onclick=()=>edit();$('#warehouseList').onclick=async e=>{const button=e.target.closest('button');if(!button)return;if(button.hasAttribute('data-new-warehouse'))edit();if(button.dataset.launch)await open(button.dataset.launch,'editor');if(button.dataset.overviewLaunch)await open(button.dataset.overviewLaunch,'overview');if(button.dataset.editWarehouse)edit(rows.find(w=>w.id===button.dataset.editWarehouse));if(button.dataset.share){sharing=button.dataset.share;$('#sharingTitle').textContent='Access · '+rows.find(w=>w.id===sharing).name;$('#sharingError').textContent='';$('#sharingDialog').showModal();await renderSharing()}};
$('#warehouseForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type="submit"]');button.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));const w=editing?await warehouseRepository.update(editing,data):await warehouseRepository.create(data);$('#warehouseDialog').close();await refreshWarehouses();callbacks.onDetails?.(w)}catch(e){$('#warehouseFormError').textContent=e.message}finally{button.disabled=false}};document.querySelectorAll('[data-close-warehouse]').forEach(b=>b.onclick=()=>$('#warehouseDialog').close());$('#closeSharing').onclick=()=>$('#sharingDialog').close();$('#memberForm').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target);try{await warehouseRepository.setMember(sharing,data.get('email'),data.get('role'));$('#sharingError').textContent='';e.target.reset();await renderSharing()}catch(e){$('#sharingError').textContent=e.message}};$('#memberList').onchange=async e=>{const email=e.target.dataset.memberRole;if(!email)return;try{await warehouseRepository.setMember(sharing,email,e.target.value);$('#sharingError').textContent='';await renderSharing()}catch(e){$('#sharingError').textContent=e.message}};$('#memberList').onclick=async e=>{const email=e.target.closest('[data-remove-member]')?.dataset.removeMember;if(!email)return;try{await warehouseRepository.removeMember(sharing,email);await renderSharing()}catch(e){$('#sharingError').textContent=e.message}};await refreshWarehouses();}

window.wsmsResetWarehouseMap=()=>warehouseMap?.reset();
